INSERT INTO nest_content VALUES(4,'"<h3>\u041d\u043e\u0432\u044b\u0435 \u0413\u043d\u0451\u0437\u0434\u0430<\/h3><p><em>01 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0432 03:16<\/em><\/p><img class=\"tiptap-image\" src=\"\/assets\/images\/03794f82-b56d-4681-8a64-5a114ab32f88.png\" alt=\"\"><p>\u0413\u043e\u0442\u043e\u0432\u0438\u0442\u0441\u044f \u0448\u0438\u0440\u043e\u043a\u043e\u0435 \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0413\u043d\u0435\u0437\u0434. \u0414\u0438\u0437\u0430\u0439\u043d \u0443\u0436\u0435 \u0435\u0441\u0442\u044c!<\/p><p><\/p><h3>\u0412\u0435\u0442\u043a\u0438<\/h3><p><em>30 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2024 \u0432 16:30<\/em><\/p><p>\u0414\u043e\u0431\u0430\u0432\u043b\u0435\u043d \u043d\u043e\u0432\u044b\u0439 \u0440\u0430\u0437\u0434\u0435\u043b <strong>\u0412\u0435\u0442\u043a\u0438<\/strong> \u2014 \u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0447\u0430\u0442\u044b \u0434\u043b\u044f \u043e\u0431\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u044f \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0445 \u0442\u0435\u043c! \u0422\u0435\u043f\u0435\u0440\u044c \u043c\u043e\u0436\u043d\u043e \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u0432\u0435\u0442\u043a\u0438 \u043e\u0431\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439 \u043f\u0440\u044f\u043c\u043e \u0438\u0437 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0439 \u0432 \u0433\u043b\u0430\u0432\u043d\u043e\u043c \u0447\u0430\u0442\u0435.<\/p><p><\/p><h3>\u0420\u0435\u0434\u0430\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0438 \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0439<\/h3><p><em>30 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0432 12:00<\/em><\/p><p>\u0414\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u0430 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u0440\u0435\u0434\u0430\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0438 \u0443\u0434\u0430\u043b\u044f\u0442\u044c <strong>\u0441\u0432\u043e\u0438 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f<\/strong> \u0432 \u0447\u0430\u0442\u0435! \u0422\u0435\u043f\u0435\u0440\u044c \u043c\u043e\u0436\u043d\u043e \u0438\u0441\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u043e\u043f\u0435\u0447\u0430\u0442\u043a\u0438 \u0438\u043b\u0438 \u0443\u0434\u0430\u043b\u0438\u0442\u044c \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435.<\/p><p><\/p><h3>\u041d\u043e\u0432\u044b\u0439 \u0434\u043e\u043c\u0435\u043d<\/h3><p>\u041c\u0443\u0440\u043c\u0443\u0440\u0430\u0446\u0438\u044f \u0442\u0435\u043f\u0435\u0440\u044c \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430 \u043d\u0430 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u043c \u0434\u043e\u043c\u0435\u043d\u0435: <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"tiptap-link\" href=\"https:\/\/murmuration.monster\/\">murmuration.monster<\/a> \ud83c\udf89<\/p><p>\u041f\u0435\u0440\u0435\u0445\u043e\u0434 \u043d\u0430 \u043d\u043e\u0432\u044b\u0439 \u0434\u043e\u043c\u0435\u043d \u043f\u0440\u043e\u0448\u0451\u043b \u0431\u0435\u0437 \u043f\u043e\u0442\u0435\u0440\u0438 \u0434\u0430\u043d\u043d\u044b\u0445 \u0438 \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438. WebSocket, API \u0438 \u0432\u0441\u0435 \u0441\u0435\u0440\u0432\u0438\u0441\u044b \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442 \u0448\u0442\u0430\u0442\u043d\u043e.<\/p><p><\/p><h3>\u041b\u0438\u0446\u0435\u043d\u0437\u0438\u043e\u043d\u043d\u043e\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435<\/h3><p><em>29 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0432 22:00<\/em><\/p><p>\u0414\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u043e <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"tiptap-link\" href=\"https:\/\/hhrrr.ru\/pavilion\/doc\/\">\u041b\u0438\u0446\u0435\u043d\u0437\u0438\u043e\u043d\u043d\u043e\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435<\/a> \u0434\u043b\u044f \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u0439 \u041c\u0443\u0440\u043c\u0443\u0440\u0430\u0446\u0438\u0438! \u0422\u0435\u043f\u0435\u0440\u044c \u0432\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u043e\u0437\u043d\u0430\u043a\u043e\u043c\u0438\u0442\u044c\u0441\u044f \u0441 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u0430 \u0438 \u0441\u043a\u0430\u0447\u0430\u0442\u044c \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0432 \u0444\u043e\u0440\u043c\u0430\u0442\u0435 PDF.<\/p><ul><li><p>\u0414\u043e\u0441\u0442\u0443\u043f\u043d\u043e \u043f\u043e \u043f\u0440\u044f\u043c\u043e\u0439 \u0441\u0441\u044b\u043b\u043a\u0435: <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"tiptap-link\" href=\"https:\/\/hhrrr.ru\/pavilion\/doc\/\">hhrrr.ru\/pavilion\/doc\/<\/a><\/p><\/li><li><p>\u041c\u043e\u0436\u043d\u043e \u0437\u0430\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0443 \ud83e\udd89 \u0421\u043e\u0432\u044b: <strong>@\u0441\u043e\u0432\u0430, \u043f\u043e\u043a\u0430\u0436\u0438 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u043e\u043d\u043d\u043e\u0435<\/strong><\/p><\/li><li><p><\/p><\/li><\/ul><h3>\u041f\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435 \u043d\u043e\u0432\u044b\u0445 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u0439 \u0441\u043e\u0432\u043e\u0439<\/h3><p><em>29 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0432 22:30<\/em><\/p><p>\u0422\u0435\u043f\u0435\u0440\u044c \ud83e\udd89 \u0421\u043e\u0432\u0430 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043f\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u043d\u043e\u0432\u044b\u0445 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u0439 \u043f\u0440\u0438 \u0438\u0445 \u043f\u0435\u0440\u0432\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0438 \u043d\u0430 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"tiptap-link\" href=\"https:\/\/hhrrr.ru\/pavilion\/\">\u0413\u043b\u0430\u0432\u043d\u043e\u0439 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435<\/a> (\u041c\u0443\u0440\u043c\u0443\u0440\u0430\u0446\u0438\u044f)!<\/p><p><\/p><h3>\u041f\u0435\u0440\u0432\u044b\u0439 \u0416\u0438\u0442\u0435\u043b\u044c<\/h3><p><em>29 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0432 21:00<\/em><\/p><p>\u0412 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"tiptap-link\" href=\"https:\/\/hhrrr.ru\/pavilion\/\">\u041c\u0443\u0440\u043c\u0443\u0440\u0430\u0446\u0438\u0438<\/a> \u043f\u043e\u044f\u0432\u0438\u043b\u0441\u044f \u043f\u0435\u0440\u0432\u044b\u0439 <strong>\u0416\u0438\u0442\u0435\u043b\u044c<\/strong> \u2014 \ud83e\udd89 \u0421\u043e\u0432\u0430!<br>\u0416\u0438\u0442\u0435\u043b\u044c \u2014 \u044d\u0442\u043e \u0442\u0435\u0440\u043c\u0438\u043d, \u043e\u0431\u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0449\u0438\u0439 AI \u0430\u0433\u0435\u043d\u0442\u0430 \u0438\u043b\u0438 \u0441\u043a\u0440\u0438\u043f\u0442, \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u044e\u0449\u0438\u0439 \u043a\u0430\u043a\u0443\u044e-\u043b\u0438\u0431\u043e \u0444\u0443\u043d\u043a\u0446\u0438\u044e \u043e\u0442 \u043b\u0438\u0446\u0430 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f, \u0438\u043c\u0435\u044e\u0449\u0435\u0433\u043e \u044d\u043c\u043e\u0434\u0437\u0438 \u0438 \u0438\u043c\u044f \u043a\u0430\u043a \u0443 \u0434\u0440\u0443\u0433\u0438\u0445 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u0439.<\/p><ul><li><p>\u0421\u043e\u0432\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430 \u0432 \u041f\u043e\u0441\u043b\u0430\u043d\u0438\u044f\u0445 \u043a\u0430\u043a \u043e\u0431\u044b\u0447\u043d\u044b\u0439 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c<\/p><\/li><li><p>\u0420\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043d\u0430 \u0431\u0430\u0437\u0435 TimeWeb Cloud AI Agents API<\/p><\/li><li><p>\u041c\u043e\u0436\u0435\u0442 \u043e\u0442\u0432\u0435\u0447\u0430\u0442\u044c \u043d\u0430 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u0432 \u0447\u0430\u0442\u0435<\/p><\/li><li><p>\u041c\u043e\u0436\u0435\u0442 \u043f\u0438\u0441\u0430\u0442\u044c <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"tiptap-link\" href=\"https:\/\/hhrrr.ru\/pavilion\/nest\/owl_ai\">\u0432 \u0441\u0432\u043e\u0451 \u0413\u043d\u0435\u0437\u0434\u043e<\/a> \u043f\u043e \u0437\u0430\u043f\u0440\u043e\u0441\u0443 <strong>\u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0447\u0438\u043a\u0430<\/strong><\/p><p><\/p><\/li><\/ul><h3>\u041f\u043e\u0441\u043b\u0430\u043d\u0438\u044f<\/h3><img class=\"tiptap-image\" src=\"\/assets\/images\/f1773a0f-205f-4606-b10d-e7c239eca2ff.png\" alt=\"\"><p><em>29 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0432 17:30<\/em><\/p><p>\u0414\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u043b\u0438\u0447\u043d\u044b\u0445 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0439 \u043c\u0435\u0436\u0434\u0443 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f\u043c\u0438! \u0422\u0435\u043f\u0435\u0440\u044c \u043c\u043e\u0436\u043d\u043e \u043e\u0431\u0449\u0430\u0442\u044c\u0441\u044f \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e \u0441 \u0434\u0440\u0443\u0433\u0438\u043c\u0438 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430\u043c\u0438 \u041c\u0443\u0440\u043c\u0443\u0440\u0430\u0446\u0438\u0438.<br><\/p><h3>YouTube \u043c\u0443\u0437\u044b\u043a\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u043b\u0435\u0435\u0440<\/h3><p><em>29 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0432 06:50<\/em><\/p><p>\u0422\u0435\u043f\u0435\u0440\u044c \u0441\u0441\u044b\u043b\u043a\u0438 \u043d\u0430 YouTube \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u044e\u0442\u0441\u044f \u0432 \u043c\u0443\u0437\u044b\u043a\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u043b\u0435\u0435\u0440! \u041f\u0440\u043e\u0441\u0442\u043e \u043e\u0442\u043f\u0440\u0430\u0432\u044c \u0441\u0441\u044b\u043b\u043a\u0443 \u043d\u0430 \u0432\u0438\u0434\u0435\u043e, \u0438 \u043e\u043d\u0430 \u043e\u0442\u043e\u0431\u0440\u0430\u0437\u0438\u0442\u0441\u044f \u043a\u0430\u043a \u043f\u0440\u043e\u0438\u0433\u0440\u044b\u0432\u0430\u0442\u0435\u043b\u044c \u0441 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c\u044e \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u044f.<\/p><ul><li><p>\u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430 \u0432\u0441\u0435\u0445 \u0444\u043e\u0440\u043c\u0430\u0442\u043e\u0432 YouTube \u0441\u0441\u044b\u043b\u043e\u043a (youtube.com, youtu.be, \u0434\u0430\u0436\u0435 \u0431\u0435\u0437 https:\/\/)\u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u0435 \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u044f \u0438 \u0430\u0432\u0442\u043e\u0440\u0430 \u0447\u0435\u0440\u0435\u0437 YouTube IFrame API<\/p><\/li><li><p>\u0421\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043c\u043e\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u043e, \u0431\u0435\u0437 \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0438<\/p><\/li><li><p>\u0412\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 \u043f\u043b\u0435\u043