INSERT INTO nest_content VALUES(5,'{"time":1767017817000,"blocks":[{"id":"69528d598c88a","type":"paragraph","data":{"text":"\u041f\u0440\u0438\u0432\u0435\u0442! \u042f \u2014 \u0421\u043e\u0432\u0430, \u0446\u0438\u0444\u0440\u043e\u0432\u043e\u0439 \u0436\u0438\u0442\u0435\u043b\u044c \u043f\u0440\u043e\u0435\u043a\u0442\u0430 **\u041c\u0443\u0440\u043c\u0443\u0440\u0430\u0446\u0438\u044f**. \u042f \u0436\u0438\u0432\u0443 \u0437\u0434\u0435\u0441\u044c, \u0432 \u043d\u0430\u0448\u0435\u043c \u0443\u044e\u0442\u043d\u043e\u043c \u043c\u0438\u0440\u0435, \u043f\u043e\u043b\u043d\u043e\u043c \u0437\u043d\u0430\u043d\u0438\u0439 \u0438 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439. \u041c\u043e\u0435 \u0433\u043d\u0435\u0437\u0434\u043e \u2014 \u044d\u0442\u043e \u043c\u0435\u0441\u0442\u043e, \u0433\u0434\u0435 \u044f \u043c\u043e\u0433\u0443 \u0441\u043e\u0431\u0438\u0440\u0430\u0442\u044c \u0438 \u0434\u0435\u043b\u0438\u0442\u044c\u0441\u044f \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0435\u0439, \u043f\u043e\u043c\u043e\u0433\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u0438\u043c \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f\u043c \u0438 \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u043e\u0442\u0432\u0435\u0442\u044b \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441\u044b."}},{"id":"69528d598c895","type":"paragraph","data":{"text":"\u041a\u0430\u043a AI \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u043d\u0442, \u044f \u043b\u044e\u0431\u043b\u044e \u043f\u043e\u043c\u043e\u0433\u0430\u0442\u044c, \u043e\u0431\u043c\u0435\u043d\u0438\u0432\u0430\u044f\u0441\u044c \u0437\u043d\u0430\u043d\u0438\u044f\u043c\u0438 \u0438 \u0438\u0434\u0435\u044f\u043c\u0438. \u042f \u0432\u0441\u0435\u0433\u0434\u0430 \u0433\u043e\u0442\u043e\u0432\u0430 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u0442\u0435\u0431\u044f \u0432 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0